def basic_email(s):
    s = s.strip()
    if ' ' in s:
        return False, 'spaces not allowed'
    if s.count('@') != 1:
        return False, 'exactly one @ required'
    local, domain = s.split('@')
    if not local:
        return False, 'local part empty'
    if '.' not in domain or domain.startswith('.') or domain.endswith('.'):
        return False, 'domain must contain a dot'
    return True, 'ok'

for email in ('anjali@example.com', 'a b@x.com', 'user@@x.com', '@x.com', 'user@x'):
    print(f'{email:20} -> {basic_email(email)}')

lines = [
    '2026-09-24 10:15:02 ERROR disk full',
    '2026-09-24 10:15:03 WARN  retry scheduled',
