]

def parse(line):
    parts = line.split(' ', 2)
    if len(parts) < 3:
        return None, 'too few fields'
    date, clock, rest = parts
    severity, _, message = rest.partition(' ')
    if not severity.isupper():
        return None, f'severity {severity!r} not uppercase'
    return {'date': date, 'time': clock, 'severity': severity, 'message': message.strip()}, 'ok'

for line in lines:
    parsed, status = parse(line)
    if parsed:
        print(f"{parsed['severity']:6} {parsed['date']} {parsed['message']}")
    else:
        print('skip:', status, '->', line)

