def normalize(text):
    words = [w.strip('.,!?;:').casefold() for w in text.split()]
    return {w for w in words if w}

def jaccard(a, b):
    set_a, set_b = normalize(a), normalize(b)
    union = set_a | set_b
    return len(set_a & set_b) / len(union) if union else 0.0, sorted(set_a & set_b)

