FIELDS = ('id', 'name', 'amount', 'country')

def extract(line):
    parts = [p.strip() for p in line.split('|')]
    row = {}
    for i, field in enumerate(FIELDS):
        raw = parts[i] if i < len(parts) else ''
        if not raw:
            row[field] = 'NA'
            continue
        if field == 'id':
            row[field] = int(raw) if raw.isdigit() else 'NA'
        elif field == 'amount':
            try:
                row[field] = float(raw.replace(',', ''))
            except ValueError:
                row[field] = 'NA'
        else:
            row[field] = ' '.join(raw.split())
    return row

for line in ('1001 |  Anjali Sharma | 122000 | India', '1002|Rehan|120,500', 'bad|data',):
    print(extract(line))

