import string
from collections import Counter

STOPWORDS = {'is', 'me', 'ka', 'ki', 'hai', 'aur', 'se', 'the', 'a', 'an', 'of', 'to', 'and', 'hai.'}

TEXT = '''Python string methods se text clean karna aasan hai.
Data cleaning is the first step of any data pipeline.
Methods like strip, split and replace are the most used methods.
'''

def normalize(text):
    return ' '.join(text.split()).casefold()

def tokens(text):
    return [w.strip(string.punctuation) for w in normalize(text).split() if w.strip(string.punctuation)]

def keywords(text, top=5, stopwords=STOPWORDS):
    kept = [w for w in tokens(text) if w not in stopwords]
    return Counter(kept).most_common(top), len(kept)

def duplicates(text):
    word_counts = Counter(tokens(text))
    lines = [normalize(line) for line in text.splitlines() if line.strip()]
    line_counts = Counter(lines)
    return ({w: c for w, c in word_counts.items() if c > 1},
            {l: c for l, c in line_counts.items() if c > 1})

def search(text, query, context=18):
    low, needle = text.casefold(), query.casefold()
    hits, pos = [], low.find(needle)
    while needle and pos != -1:
        end = pos + len(needle)
        hits.append((pos, text[max(0, pos - context):end + context].replace(chr(10), ' ')))
        pos = low.find(needle, end)
    return hits

total = len(tokens(TEXT))
print(f'tokens: {total} | unique: {len(set(tokens(TEXT)))}')

top_terms, kept = keywords(TEXT)
print(f'keywords (kept {kept}):')
for word, count in top_terms:
    print(f'  {word:12} {count}')

dup_words, dup_lines = duplicates(TEXT)
print('duplicate words:', dup_words)
print('duplicate lines:', len(dup_lines))

print('search \'data\':')
for pos, snippet in search(TEXT, 'data'):
    print(f'  @{pos:<4} ...{snippet}...')

import json, string
from collections import Counter, defaultdict

class TextError(ValueError):
    pass

STEPS = {
    'casefold': lambda tokens: [t.casefold() for t in tokens],
    'strip_punct': lambda tokens: [t.strip(string.punctuation) for t in tokens],
    'drop_empty': lambda tokens: [t for t in tokens if t],
    'drop_stop': lambda tokens: [t for t in tokens if t not in {'is', 'me', 'ka', 'ki', 'hai', 'the', 'a', 'of', 'and'}],
    'min_len': lambda tokens: [t for t in tokens if len(t) > 2],
}

def process(text, steps):
    unknown = [s for s in steps if s not in STEPS]
    if unknown:
        raise TextError(f'unknown steps {unknown}; available {sorted(STEPS)}')
    if not isinstance(text, str):
        raise TextError(f'text must be str, got {type(text).__name__}')
    tokens = text.split()
    for step in steps:
        tokens = STEPS[step](tokens)
    return tokens

class TextSystem:
    def __init__(self, steps=('casefold', 'strip_punct', 'drop_empty', 'drop_stop')):
        self.steps = steps
        self.tokens = []
        self.index = defaultdict(list)

    def load(self, name, text):
        self.tokens = process(text, self.steps)
        self.index = defaultdict(list)
        for pos, token in enumerate(self.tokens):
            self.index[token].append(pos)
        return self

    def search(self, term):
        term = term.casefold()
        return self.index.get(term, [])

    def keywords(self, top=5):
        return Counter(self.tokens).most_common(top)

    def stats(self):
        return {
            'tokens': len(self.tokens),
            'unique': len(self.index),
            'avg_len': round(sum(map(len, self.tokens)) / len(self.tokens), 2) if self.tokens else 0.0,
            'longest': max(self.tokens, key=len, default=''),
        }

    def similarity(self, other_text):
        other = set(process(other_text, self.steps))
        mine = set(self.tokens)
        union = mine | other
        return round(len(mine & other) / len(union), 3) if union else 0.0

    def export(self, fmt='json'):
        payload = {'stats': self.stats(), 'top': self.keywords(), 'index_size': len(self.index)}
        if fmt == 'json':
            return json.dumps(payload, ensure_ascii=False)
        if fmt == 'text':
            lines = [f'{k:10}: {v}' for k, v in payload['stats'].items()]
            lines += [f"top       : {payload['top']}"]
            return chr(10).join(lines)
        raise TextError(f'unsupported format {fmt!r}; use json or text')

DOC = '''Python string methods se text clean karna aasan hai.
Data cleaning is the first step of a data pipeline!'''

system = TextSystem().load('doc1', DOC)
print(system.export('text'))
print()
print('search "data"   :', system.search('data'))
print('search "machine":', system.search('machine'))
print('similarity (same doc) :', system.similarity(DOC))
print('similarity (other)    :', system.similarity('NumPy arrays and pandas dataframes for data work'))
print('json (first 110)      :', system.export('json')[:110] + ' ...')

for bad_call in (lambda: process('text', ['nope']), lambda: process(123, ['casefold']), lambda: system.export('pdf')):
